TITLE: Safely Manage Database Connection Lifecycle with acquireRelease (TypeScript)
DESCRIPTION: This snippet demonstrates how to safely acquire and release a database connection using Effect.js's `acquireRelease` effect. It ensures that the connection is always closed after use, even if errors occur. This pattern is crucial for preventing resource leaks in applications.

SOURCE: https://github.com/pauljphilp/effectpatterns/blob/main/rules/by-use-case/database-connections.md

LANGUAGE: typescript
CODE:
```
import { Effect, Console } from "effect";

// A mock resource that needs to be managed
const getDbConnection = Effect.sync(() => ({ id: Math.random() })).pipe(
  Effect.tap(() => Effect.log("Connection Acquired")),
);

const closeDbConnection = (conn: { id: number }): Effect.Effect<void, never, never> =>
  Effect.log(`Connection ${conn.id} Released`);

// The program that uses the resource
const program = Effect.acquireRelease(
  getDbConnection, // 1. acquire
  (connection) => closeDbConnection(connection) // 2. cleanup
).pipe(
  Effect.tap((connection) =>
    Effect.log(`Using connection ${connection.id} to run query...`)
  )
);

Effect.runPromise(Effect.scoped(program));

/*
Output:
Connection Acquired
Using connection 0.12345... to run query...
Connection 0.12345... Released
*/
```

