  Config.map(c => new AppConfig(c.srcDir, c.processedDir))
);

// Live implementation of AppConfig, to be provided as a Layer
export const AppConfigLive = loadAppConfig.pipe(
  Effect.provideLayer(Config.layerFromEnvironment())
);

