TITLE: Process Stream Items in Batches (TypeScript)
DESCRIPTION: This example demonstrates how to transform a stream of items into a stream of batched chunks using `Stream.grouped(n)`. It processes 10 users, grouping them into batches of 5, and then calls a bulk save function only twice, once for each batch.

SOURCE: https://github.com/pauljphilp/effectpatterns/blob/main/rules/by-use-case/building-data-pipelines.md

LANGUAGE: typescript
CODE:
```
import { Effect, Stream, Chunk } from 'effect';

// A mock function that simulates a bulk database insert
const saveUsersInBulk = (
  userBatch: Chunk.Chunk<{ id: number }> ): Effect.Effect<void, Error> =>
  Effect.log(
    `Saving batch of ${userBatch.length} users: ${Chunk.toArray(userBatch)
      .map((u) => u.id)
      .join(', ')}`
  );

const userIds = Array.from({ length: 10 }, (_, i) => ({ id: i + 1 }));

const program = Stream.fromIterable(userIds).pipe(
  // Group the stream of users into batches of 5
  Stream.grouped(5),
  // Process each batch with our bulk save function
  Stream.mapEffect(saveUsersInBulk, { concurrency: 1 }),
  Stream.runDrain
);

Effect.runPromise(program);
