TITLE: Safely Find User by ID with Option<User>
DESCRIPTION: This TypeScript code demonstrates how to use `Option.Option<User>` to safely represent a user that may or may not be found in a database. It uses `Option.fromNullable` to convert a potentially null result from `Array.find` into an `Option`. The `Option.match` function is then used to handle both the `Some` (user found) and `None` (user not found) cases explicitly, preventing runtime errors.

SOURCE: https://github.com/pauljphilp/effectpatterns/blob/main/content/published/model-optional-values-with-option.mdx

LANGUAGE: typescript
CODE:
```
import { Effect, Option } from "effect";

interface User {
  id: number;
  name: string;
}

const users: User[] = [
  { id: 1, name: "Paul" },
  { id: 2, name: "Alex" },
];

// This function safely returns an Option, not a User or null.
const findUserById = (id: number): Option.Option<User> => {
  const user = users.find((u) => u.id === id);
  return Option.fromNullable(user); // A useful helper for existing APIs
};

// The caller MUST handle both cases.
const greeting = (id: number): string =>
  findUserById(id).pipe(
    Option.match({
      onNone: () => "User not found.",
      onSome: (user) => `Welcome, ${user.name}!`,
    }),
  );

const program = Effect.gen(function* () {
  yield* Effect.log(greeting(1)); // "Welcome, Paul!"
  yield* Effect.log(greeting(3)); // "User not found."
});

Effect.runPromise(program);
```

