export class AppConfig extends Effect.TaggedClass<AppConfig>() {
  constructor(readonly srcDir: string, readonly processedDir: string) {
    super();
  }
}

// Define configuration schema for AppConfig
const AppConfigSchema = Config.struct({
  srcDir: Config.string("SRC_DIR").withDefault(Path.join(process.cwd(), "content/new/src")),
  processedDir: Config.string("PROCESSED_DIR").withDefault(Path.join(process.cwd(), "content/new/processed")),
});

