  yield* Effect.log(`HashSet.has(set, {id:1,name:'Alice'}): ${hasUser}`);
  yield* Effect.log(
    `Sorted users by id: [${sorted.map((u) => u.name).join(", ")}]`
  );
});

Effect.runPromise(
  program.pipe(Effect.catchAll(() => Effect.succeed(undefined)))
);

