### Manual Retry Logic (Anti-Pattern) in TypeScript

Source: https://github.com/pauljphilp/effectpatterns/blob/main/rules/generated/rules-for-claude.md

Presents an anti-pattern of manual, imperative retry logic in TypeScript. This approach is verbose, stateful, and hard to reason about compared to using Schedule. It requires manual management of retries and delays. Imports 'Effect' from 'effect'.

```typescript
import { Effect } from "effect";
import { flakyEffect } from "./somewhere";

// ❌ WRONG: Manual, stateful, and complex retry logic.
function manualRetry(
  effect: typeof flakyEffect,
  retriesLeft: number,
  delay: number,
): Effect.Effect<string, "ApiError">
{
  return effect.pipe(
    Effect.catchTag("ApiError", () => {
      if (retriesLeft > 0) {
        return Effect.sleep(delay).pipe(
          Effect.flatMap(() => manualRetry(effect, retriesLeft - 1, delay * 2)),
        );
      }
      return Effect.fail("ApiError" as const);
    }),
  );
}

const program = manualRetry(flakyEffect, 5, 100);

